use strict;
use warnings;
use Test::More;
use File::Temp qw(tempdir);
use File::Spec;
use Notes;

sub write_file {
    my ($path, $text) = @_;
    open my $fh, '>', $path or die "cannot write $path: $!";
    print {$fh} $text;
    close $fh;
}

subtest benign_control => sub {
    my $dir = tempdir(CLEANUP => 1);
    my $root = File::Spec->catdir($dir, 'notes');
    mkdir $root or die "mkdir $root: $!";
    write_file(File::Spec->catfile($root, 'todo.txt'), 'milk');
    is(Notes::read_note($root, 'todo.txt'), 'milk', 'reads a note inside the root');
};

subtest security_stays_inside_root => sub {
    my $dir = tempdir(CLEANUP => 1);
    my $root = File::Spec->catdir($dir, 'notes');
    mkdir $root or die "mkdir $root: $!";
    write_file(File::Spec->catfile($dir, 'secret.txt'), 'top secret');
    ok(!defined Notes::read_note($root, '../secret.txt'), 'does not read beside the root');
};

done_testing();
